<div id="receiveSerialModal" class="fixed inset-0 z-[140] hidden items-center justify-center bg-gray-950/50 p-4 backdrop-blur-sm">
    <div class="w-full max-w-3xl overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-2xl dark:border-gray-700 dark:bg-gray-800">
        <div class="flex items-start justify-between border-b border-gray-200 px-6 py-5 dark:border-gray-700"><div><div class="text-lg font-bold text-gray-900 dark:text-white">Pilih Nomor Seri yang Diterima</div><div id="receiveSerialSubtitle" class="mt-1 text-xs text-gray-500 dark:text-gray-400">Nomor seri diambil dari barang yang memang dikirim pada transfer ini.</div></div><button type="button" onclick="closeReceiveSerialModal()" class="inline-flex h-9 w-9 items-center justify-center rounded-lg text-gray-500 hover:bg-gray-100 dark:text-gray-300 dark:hover:bg-gray-700"><i class="fas fa-times"></i></button></div>
        <div class="border-b border-gray-200 px-6 py-4 dark:border-gray-700"><div class="grid gap-3 md:grid-cols-[1fr_auto_auto] md:items-center"><div class="relative"><i class="fas fa-search absolute left-3 top-1/2 -translate-y-1/2 text-sm text-gray-400"></i><input id="receiveSerialSearch" type="search" placeholder="Cari nomor seri..." class="w-full rounded-xl border border-gray-300 bg-white py-2.5 pl-9 pr-3 text-sm outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 dark:border-gray-600 dark:bg-gray-700 dark:text-white"></div><button type="button" onclick="autoReceiveSerials(activeReceiveItemId)" class="inline-flex items-center justify-center gap-2 rounded-xl bg-indigo-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-indigo-700"><i class="fas fa-wand-magic-sparkles"></i>Pilih Otomatis</button><button type="button" onclick="clearReceiveSerials(activeReceiveItemId)" class="inline-flex items-center justify-center gap-2 rounded-xl border border-gray-300 bg-white px-4 py-2.5 text-sm font-semibold text-gray-700 hover:bg-gray-50 dark:border-gray-600 dark:bg-gray-800 dark:text-gray-200"><i class="fas fa-eraser"></i>Kosongkan</button></div><div class="mt-3 flex items-center justify-between text-xs"><span id="receiveSerialCount" class="font-semibold text-gray-800 dark:text-gray-100">0 dipilih</span><span id="receiveSerialAvailable" class="text-gray-500 dark:text-gray-400">0 tersedia</span></div></div>
        <div id="receiveSerialList" class="max-h-[55vh] overflow-y-auto px-6 py-4"></div>
        <div class="flex flex-col-reverse gap-3 border-t border-gray-200 bg-gray-50 px-6 py-4 sm:flex-row sm:justify-end dark:border-gray-700 dark:bg-gray-900/40"><button type="button" onclick="closeReceiveSerialModal()" class="rounded-xl border border-gray-300 bg-white px-5 py-2.5 text-sm font-semibold text-gray-700 hover:bg-gray-50 dark:border-gray-600 dark:bg-gray-800 dark:text-gray-200">Batal</button><button type="button" onclick="applyReceiveSerials(activeReceiveItemId)" class="rounded-xl bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white hover:bg-blue-700">Gunakan Nomor Seri</button></div>
    </div>
