<script>
function printSuratJalan(){window.location.hash='surat-jalan';window.print();}
<?php if($canReceive): ?>
const receiveSerialData = <?=json_encode(array_reduce($items,function($carry,$item) use ($serialMap){$pending=array_values(array_filter($serialMap[(int)$item['id']]??[],fn($s)=>$s['status']==='IN_TRANSIT'));$carry[(string)$item['id']] = array_map(fn($s)=>$s['serial_number'],$pending);return $carry;},[]),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
let activeReceiveItemId=null;
let workingReceiveSelections={};
function getReceiveQty(itemId){const el=document.querySelector(`.receive-qty[data-item-id="${itemId}"]`);return el?parseInt(el.value||'0',10):0;}
function ensureReceiveSelection(itemId){if(!workingReceiveSelections[itemId]) workingReceiveSelections[itemId]=new Set(); return workingReceiveSelections[itemId];}
function renderReceiveSummary(itemId){const set=ensureReceiveSelection(itemId);const box=document.querySelector(`.receive-serial-summary-${itemId}`);if(!box)return;if(!set.size){box.textContent='Belum dipilih';return;}const arr=Array.from(set);const preview=arr.slice(0,5).map(sn=>`<span class="inline-flex rounded-lg border border-blue-100 bg-blue-50 px-2 py-1 font-mono text-[11px] text-blue-700 dark:border-blue-900/50 dark:bg-blue-950/30 dark:text-blue-300">${escapeHtmlTransfer(sn)}</span>`).join('');const extra=arr.length>5?`<span class="inline-flex rounded-lg bg-gray-100 px-2 py-1 text-[11px] font-semibold text-gray-600 dark:bg-gray-700 dark:text-gray-200">+${arr.length-5} lainnya</span>`:'';box.innerHTML=`<div class="mb-2 text-xs font-semibold text-gray-700 dark:text-gray-200">${arr.length} nomor seri dipilih</div><div class="flex flex-wrap gap-1.5">${preview}${extra}</div>`;}
function escapeHtmlTransfer(value){return String(value).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
function autoReceiveSerials(itemId){const qty=getReceiveQty(itemId);const available=receiveSerialData[String(itemId)]||[];workingReceiveSelections[itemId]=new Set(available.slice(0,qty));applyReceiveSerials(itemId,true);}
function clearReceiveSerials(itemId){workingReceiveSelections[itemId]=new Set();const input=document.getElementById(`receive-sn-${itemId}`);if(input)input.value='';renderReceiveSummary(itemId);}
function openReceiveSerialModal(itemId){activeReceiveItemId=String(itemId);const qty=getReceiveQty(itemId);const available=receiveSerialData[String(itemId)]||[];const input=document.getElementById(`receive-sn-${itemId}`);const current=String(input?.value||'').split(/\n+/).map(v=>v.trim()).filter(Boolean);workingReceiveSelections[itemId]=new Set(current);document.getElementById('receiveSerialSubtitle').textContent=`Jumlah diterima sekarang: ${qty}. Pilih dari ${available.length} nomor seri yang masih dalam pengiriman.`;document.getElementById('receiveSerialSearch').value='';document.getElementById('receiveSerialModal').classList.remove('hidden');document.getElementById('receiveSerialModal').classList.add('flex');document.body.classList.add('overflow-hidden');renderReceiveSerialList(itemId);setTimeout(()=>document.getElementById('receiveSerialSearch').focus(),50);}
function closeReceiveSerialModal(){const modal=document.getElementById('receiveSerialModal');if(modal){modal.classList.add('hidden');modal.classList.remove('flex');}document.body.classList.remove('overflow-hidden');activeReceiveItemId=null;}
function renderReceiveSerialList(itemId){const available=receiveSerialData[String(itemId)]||[];const q=String(document.getElementById('receiveSerialSearch').value||'').trim().toLowerCase();const filtered=available.filter(sn=>sn.toLowerCase().includes(q));const set=ensureReceiveSelection(itemId);const qty=getReceiveQty(itemId);document.getElementById('receiveSerialCount').textContent=`${set.size} / ${qty} dipilih`;document.getElementById('receiveSerialAvailable').textContent=`${available.length} nomor seri dikirim`;const list=document.getElementById('receiveSerialList');if(!filtered.length){list.innerHTML='<div class="rounded-xl border border-dashed border-gray-300 p-8 text-center text-sm text-gray-500 dark:border-gray-600 dark:text-gray-400">Nomor seri tidak ditemukan.</div>';return;}list.innerHTML=filtered.map(sn=>{const checked=set.has(sn);return `<label class="mb-2 flex cursor-pointer items-center gap-3 rounded-xl border px-4 py-3 transition ${checked?'border-blue-300 bg-blue-50 dark:border-blue-800 dark:bg-blue-950/30':'border-gray-200 bg-white hover:bg-gray-50 dark:border-gray-700 dark:bg-gray-800 dark:hover:bg-gray-700'}"><input type="checkbox" class="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500" data-sn="${escapeHtmlTransfer(sn)}" ${checked?'checked':''} onchange="toggleReceiveSerial('${String(itemId)}',this)"><span class="font-mono text-sm text-gray-800 dark:text-gray-100">${escapeHtmlTransfer(sn)}</span></label>`;}).join('');}
function toggleReceiveSerial(itemId,checkbox){const set=ensureReceiveSelection(itemId);const qty=getReceiveQty(itemId);const sn=checkbox.dataset.sn;if(checkbox.checked){if(set.size>=qty){checkbox.checked=false;return;}set.add(sn);}else set.delete(sn);renderReceiveSerialList(itemId);}
function applyReceiveSerials(itemId,fromAuto=false){const set=ensureReceiveSelection(itemId);const qty=getReceiveQty(itemId);if(set.size!==qty){if(!fromAuto){const count=document.getElementById('receiveSerialCount');count.className='font-semibold text-red-600';count.textContent=`Harus memilih tepat ${qty} nomor seri`; }return false;}const input=document.getElementById(`receive-sn-${itemId}`);if(input)input.value=Array.from(set).join('\n');renderReceiveSummary(itemId);if(!fromAuto)closeReceiveSerialModal();return true;}
function terimaSemua(){document.querySelectorAll('[data-receive-row]').forEach(row=>{const id=row.dataset.receiveRow;const remaining=parseInt(row.dataset.remaining||'0',10);const qty=row.querySelector('.receive-qty');if(qty)qty.value=remaining;if(row.dataset.serialized==='1')autoReceiveSerials(id);});}
document.getElementById('receiveSerialSearch')?.addEventListener('input',()=>{if(activeReceiveItemId!==null)renderReceiveSerialList(activeReceiveItemId);});
document.getElementById('receiveSerialModal')?.addEventListener('click',e=>{if(e.target.id==='receiveSerialModal')closeReceiveSerialModal();});
document.querySelectorAll('.receive-qty').forEach(input=>input.addEventListener('input',()=>{const id=input.dataset.itemId;const max=parseInt(input.max||'0',10);let value=parseInt(input.value||'0',10);if(value<0)value=0;if(max>0&&value>max)value=max;input.value=value;if((document.querySelector(`[data-receive-row="${id}"]`)?.dataset.serialized==='1')){const set=ensureReceiveSelection(id);if(set.size>value){const trimmed=Array.from(set).slice(0,value);workingReceiveSelections[id]=new Set(trimmed);const hidden=document.getElementById(`receive-sn-${id}`);if(hidden)hidden.value=trimmed.join('\n');}renderReceiveSummary(id);}}));
document.getElementById('receiveForm')?.addEventListener('submit',e=>{let valid=true;document.querySelectorAll('[data-receive-row]').forEach(row=>{const id=row.dataset.receiveRow;const qty=parseInt(row.querySelector('.receive-qty')?.value||'0',10);if(qty<=0)return;if(row.dataset.serialized==='1'){const set=ensureReceiveSelection(id);if(set.size!==qty)valid=false;}});if(!valid){e.preventDefault();if(window.AppToast&&typeof window.AppToast.error==='function')AppToast.error('Lengkapi jumlah dan pilihan nomor seri sesuai barang yang benar-benar diterima.','Data penerimaan belum lengkap');else window.dispatchEvent(new CustomEvent('bignet:toast',{detail:{type:'error',message:'Lengkapi jumlah dan pilihan nomor seri sesuai barang yang benar-benar diterima.'}}));}});
<?php endif; ?>
</script>
<?php $content=ob_get_clean(); require __DIR__.'/../../layouts/app.php'; ?>


